// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetRepository Read the repository linked to a project
	// (GET /organizations/{id}/projects/{projectId}/repository)
	GetRepository(ctx context.Context, request GetRepositoryRequestObject) (GetRepositoryResponseObject, error)
	// LinkRepository Link a Git repository to a project, or change its address
	// (PUT /organizations/{id}/projects/{projectId}/repository)
	LinkRepository(ctx context.Context, request LinkRepositoryRequestObject) (LinkRepositoryResponseObject, error)
	// ConfirmDeployKey Stop using the previous deploy key
	// (POST /organizations/{id}/projects/{projectId}/repository/confirm-deploy-key)
	ConfirmDeployKey(ctx context.Context, request ConfirmDeployKeyRequestObject) (ConfirmDeployKeyResponseObject, error)
	// ConfirmHostKey Pin the pending host key
	// (POST /organizations/{id}/projects/{projectId}/repository/confirm-host-key)
	ConfirmHostKey(ctx context.Context, request ConfirmHostKeyRequestObject) (ConfirmHostKeyResponseObject, error)
	// RotateDeployKey Make a new deploy key
	// (POST /organizations/{id}/projects/{projectId}/repository/rotate-deploy-key)
	RotateDeployKey(ctx context.Context, request RotateDeployKeyRequestObject) (RotateDeployKeyResponseObject, error)
	// RotateWebhookSecret Make a new webhook secret
	// (POST /organizations/{id}/projects/{projectId}/repository/rotate-webhook-secret)
	RotateWebhookSecret(ctx context.Context, request RotateWebhookSecretRequestObject) (RotateWebhookSecretResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetRepository operation middleware
func (sh *strictHandler) GetRepository(w http.ResponseWriter, r *http.Request, id Id, projectId ProjectId) {
	var request GetRepositoryRequestObject

	request.Id = id
	request.ProjectId = projectId

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetRepository(ctx, request.(GetRepositoryRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetRepository")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetRepositoryResponseObject); ok {
		if err := validResponse.VisitGetRepositoryResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

